import { motion } from "framer-motion";
import { useState } from "react";
import { useInView } from "react-intersection-observer";
import Stepper, { Step } from '../components/Stepper';
import "../styles/Contact.css";
import { slideInBottom } from "../utils/animations";

const Contact = () => {
  const [formData, setFormData] = useState({ email: "", message: "" });
  const [name, setName] = useState("");
  const [ref, inView] = useInView({
    triggerOnce: true,
    threshold: 0.1
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Create mailto link with form data
    const subject = encodeURIComponent(`Message from ${name || 'Portfolio Contact'}`);
    const body = encodeURIComponent(
      `Name: ${name || 'Not provided'}\n\n` +
      `Email: ${formData.email}\n\n` +
      `Message:\n${formData.message}`
    );

    const mailtoLink = `mailto:kushalkumar2506@gmail.com?subject=${subject}&body=${body}`;

    // Open email client
    window.location.href = mailtoLink;

    // Reset form after opening email client
    setFormData({ email: "", message: "" });
    setName("");
  };

  return (
    <section id="contact" className="contact-section">
      <motion.h2 
        className="section-title"
        initial={{ opacity: 0, y: 20 }}
        animate={inView ? { opacity: 1, y: 0 } : { opacity: 0, y: 20 }}
        transition={{ duration: 0.6 }}
      >
        Get in Touch!
      </motion.h2>
      <motion.div 
        ref={ref}
        className="stepper-section"
        variants={slideInBottom}
        initial="initial"
        animate={inView ? "animate" : "initial"}
      >
        <Stepper
          initialStep={1}
          onStepChange={(step) => {
            console.log(step);
          }}
          onFinalStepCompleted={() => console.log("All steps completed!")}
          backButtonText="Previous"
          nextButtonText="Next"
          hideCompleteButton={true}
        >
          <Step>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
            >
              <h2>I look forward to collaborating with you and achieving remarkable results together.</h2>
              <p>Check out the next step!</p>
            </motion.div>
          </Step>

          <Step>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
            >
              <h2>Let's get to know you</h2>
              <motion.input 
                value={name} 
                onChange={(e) => setName(e.target.value)} 
                placeholder="Your name?"
                whileFocus={{ scale: 1.02 }}
                transition={{ duration: 0.2 }}
              />
            </motion.div>
          </Step>

          <Step>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
            >
              <h2>Your Contact Information</h2>
              <motion.input 
                type="email"
                value={formData.email} 
                onChange={handleChange}
                name="email"
                placeholder="Your email address?"
                whileFocus={{ scale: 1.02 }}
                transition={{ duration: 0.2 }}
              />
            </motion.div>
          </Step>

          <Step>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
            >
              <h2>What's on your mind?</h2>
              <motion.textarea 
                value={formData.message} 
                onChange={handleChange}
                name="message"
                placeholder="Write your message..."
                className="stepper-input"
                whileFocus={{ scale: 1.02 }}
                transition={{ duration: 0.2 }}
              />
            </motion.div>
          </Step>

          <Step>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
            >
              <h2>Ready to Send!</h2>
              <p>Click the button below to send your message via email.</p>
              <motion.button
                onClick={handleSubmit}
                className="contact-submit-btn"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                transition={{ duration: 0.2 }}
              >
                Send Email
              </motion.button>
            </motion.div>
          </Step>
        </Stepper>
      </motion.div>
    </section>
  );
};

export default Contact;
